INSERT INTO public.usoap_protocol_question (id, name, deleted, description, created_at, modified_at, code, texto, critical_element, area_code, created_by_id, modified_by_id) VALUES
    ('a01m02zkj57ebm8pq659gkj2kkh', NULL, 'f', NULL, '2026-08-15 15:10:51', '2026-08-15 15:10:51', 'PQ 7.001', '¿Ha elaborado y promulgado el Estado legislación aeronáutica en cumplimiento, sin excepción, de las disposiciones aplicables del Anexo 2 para alta mar?', 'a01m00yht41e3x98rc78kmhvz40', NULL, '1', '1'),
    ('a01m02zkj96e7ar45vqr4c3wxcv', NULL, 'f', NULL, '2026-08-15 15:10:51', '2026-08-15 15:10:51', 'PQ 7.003', '¿Ha promulgado el Estado legislación aeronáutica básica que garantice la prestación de servicios de navegación aérea (ANS) que exige el Artículo 28 del Convenio de Chicago?', 'a01m00yht41e3x98rc78kmhvz40', NULL, '1', '1'),
    ('a01m02zkjcye3sbeha8nydekk7y', NULL, 'f', NULL, '2026-08-15 15:10:51', '2026-08-15 15:10:51', 'PQ 7.005', '¿Ha promulgado el Estado legislación aeronáutica básica que facilite la asistencia a las aeronaves en peligro en su territorio en adhesión al Artículo 25 del Convenio de Chicago?', 'a01m00yht41e3x98rc78kmhvz40', NULL, '1', '1'),
    ('a01m02zkjgsefxr2htzrjwvm05x', NULL, 'f', NULL, '2026-08-15 15:10:51', '2026-08-15 15:10:51', 'PQ 7.007', '¿Ha publicado el Estado reglamentos de explotación específicos relativos a la interceptación de aeronaves civiles sobre su territorio?', 'a01m00yj2eye3xrkgj0e4yy3400', NULL, '1', '1'),
    ('a01m02zkjneee596k799bgthjyk', NULL, 'f', NULL, '2026-08-15 15:10:51', '2026-08-15 15:10:51', 'PQ 7.009', '¿Ha promulgado el Estado reglamentos de explotación específicos de ANS que incorporen las disposiciones relacionadas con los ANS de los Anexos 2, 3, 4, 5, 10, 11, 12 y 15?', 'a01m00yj2eye3xrkgj0e4yy3400', NULL, '1', '1'),
    ('a01m02zkjsnef2spthfdwz27dqq', NULL, 'f', NULL, '2026-08-15 15:10:51', '2026-08-15 15:10:51', 'PQ 7.011', '¿Aplica el Estado procedimientos para enmendar sus reglamentos específicos de ANS y detectar y notificar las diferencias, tomando en consideración las disposiciones de la OACI y sus enmiendas?', 'a01m00yj2eye3xrkgj0e4yy3400', NULL, '1', '1'),
    ('a01m02zkjxpee69sj07xgaeszvy', NULL, 'f', NULL, '2026-08-15 15:10:51', '2026-08-15 15:10:51', 'PQ 7.031', '¿Ha establecido el Estado una estructura orgánica con funciones relacionadas con la vigilancia de la seguridad operacional de los proveedores de ANS?', 'a01m00yj2sne659acsgtnf82b6h', NULL, '1', '1'),
    ('a01m02zkk1jefp82m16brpdhatw', NULL, 'f', NULL, '2026-08-15 15:10:51', '2026-08-15 15:10:51', 'PQ 7.037', '¿Ha elaborado el Estado procedimientos que faciliten a los inspectores ANS el desempeño de sus funciones de vigilancia de la seguridad operacional de manera normalizada y eficaz?', 'a01m00yj3d9e9fb7j59wynx6239', NULL, '1', '1'),
    ('a01m02zkk5ne0cvgwxacmpsbj2h', NULL, 'f', NULL, '2026-08-15 15:10:52', '2026-08-15 15:10:52', 'PQ 7.039', '¿Están a disposición de todo el personal de inspección de ANS los documentos pertinentes de la OACI y demás publicaciones técnicas y de reglamentación?', 'a01m00yj3d9e9fb7j59wynx6239', NULL, '1', '1'),
    ('a01m02zkk9ze5famvf4ygvw2cwe', NULL, 'f', NULL, '2026-08-15 15:10:52', '2026-08-15 15:10:52', 'PQ 7.042', '¿Cuentan los inspectores ANS con credenciales con derecho de acceso a instalaciones aeronáuticas estatales y documentación relacionadas con los proveedores de servicios para poder inspeccionarlas y hacer cumplir los reglamentos?', 'a01m00yj2sne659acsgtnf82b6h', NULL, '1', '1'),
    ('a01m02zkkdve4h89q7pqv2qznqa', NULL, 'f', NULL, '2026-08-15 15:10:52', '2026-08-15 15:10:52', 'PQ 7.045', '¿Ha establecido e implantado el Estado un mecanismo para examinar y eliminar las deficiencias detectadas en el marco de los grupos regionales de planificación y ejecución (PIRG)?', 'a01m00yj4cbe0r9pq5520v6kvcv', NULL, '1', '1'),
    ('a01m02zkkj4e31arpb7xmaf327n', NULL, 'f', NULL, '2026-08-15 15:10:52', '2026-08-15 15:10:52', 'PQ 7.051', 'Si el Estado participa en el suministro de ANS, ¿existe una separación clara entre las funciones de reglamentación y las de suministro de servicios en todos los campos de ANS?', 'a01m00yj2sne659acsgtnf82b6h', NULL, '1', '1'),
    ('a01m02zkkp8e1x9w4p1bt9nkpdj', NULL, 'f', NULL, '2026-08-15 15:10:52', '2026-08-15 15:10:52', 'PQ 7.057', '¿Ha establecido el Estado para los inspectores ATS:
