    ('a01m02zk568ea2r7hr5g5a75n0s', NULL, 'f', NULL, '2026-08-15 15:10:37', '2026-08-15 15:10:37', 'PQ 8.162', '¿Ha promulgado el Estado reglamentos sobre las características físicas de los aeródromos?', 'a01m00yj2eye3xrkgj0e4yy3400', '["a01m00yjdfhe0dvwfpsg29atxzs"]', '1', '1'),
