    ('a01m02zka7jeemafqx5zvdnck1g', NULL, 'f', NULL, '2026-08-15 15:10:42', '2026-08-15 15:10:42', 'PQ 8.281', '¿Proporciona el Estado suficiente orientación sobre el control de obstáculos al personal normativo y a la industria?', 'a01m00yj3d9e9fb7j59wynx6239', '["a01m00yjdfhe0dvwfpsg29atxzs"]', '1', '1'),
